parameters.jsCode:
const items = $input.all();

return items.map((item, index) => {
  const input = item.json ?? {};

  // Supports several possible OpenAI node output structures.
  let raw =
    input.output?.[0]?.content?.[0]?.text ??
    input.output_text ??
    input.text ??
    input.message?.content ??
    input.content?.[0]?.text ??
    input.content ??
    '{}';

  // If the output is already an object, use it directly.
  let parsed = {};

  if (typeof raw === 'object' && raw !== null) {
    parsed = raw;
  } else {
    const cleaned = String(raw)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    try {
      parsed = JSON.parse(cleaned);
    } catch (error) {
      parsed = {};
    }
  }

  const validPriority = ['High', 'Medium', 'Low'];
  const validLeadType = ['Hot', 'Warm', 'Cold'];
  const validSentiment = ['Positive', 'Neutral', 'Negative'];
  const validROI = ['High', 'Medium', 'Low', 'Not Specified'];

  const score = Number(parsed['AI Lead Score'] ?? parsed.AILeadScore ?? 0);

  return {
    json: {
      ...input,

      'AI Priority': validPriority.includes(
        parsed['AI Priority'] ?? parsed.AIPriority
      )
        ? parsed['AI Priority'] ?? parsed.AIPriority
        : 'Medium',

      'AI Lead Score': Number.isFinite(score)
        ? Math.min(100, Math.max(0, Math.round(score)))
        : 0,

      'AI Lead Type': validLeadType.includes(
        parsed['AI Lead Type'] ?? parsed.AILeadType
      )
        ? parsed['AI Lead Type'] ?? parsed.AILeadType
        : 'Warm',

      Language:
        parsed.Language ||
        'English',

      Sentiment: validSentiment.includes(parsed.Sentiment)
        ? parsed.Sentiment
        : 'Neutral',

      'Assigned Team':
        parsed['Assigned Team'] ||
        parsed.AssignedTeam ||
        'General Sales Team',

      'Investment Type':
        parsed['Investment Type'] ||
        parsed.InvestmentType ||
        'General Enquiry',

      'Property Type':
        parsed['Property Type'] ||
        parsed.PropertyType ||
        'Not Specified',

      'ROI Interest': validROI.includes(
        parsed['ROI Interest'] ?? parsed.ROIInterest
      )
        ? parsed['ROI Interest'] ?? parsed.ROIInterest
        : 'Not Specified',
    },

    // Preserves the relationship with the corresponding input item.
    pairedItem: { item: index },
  };
});

parameters.value:
={{ JSON.stringify({
  maxSize: 1,
  where: [
    {
      type: "or",
      value: [
        {
          type: "equals",
          attribute: "emailAddress",
          value: $('Lead Webhook (HTTP)').item.json.body.Email
        },
        {
          type: "equals",
          attribute: "phoneNumber",
          value: (() => {
            const p = String(
              $('Lead Webhook (HTTP)').item.json.body.Phone || ''
            ).replace(/[^0-9+]/g, '');

            if (p.startsWith('+971')) return p;
            if (p.startsWith('971')) return '+' + p;
            if (p.startsWith('0')) return '+971' + p.substring(1);
            if (p.startsWith('5')) return '+971' + p;

            return p;
          })()
        }
      ]
    }
  ]
}) }}

